# Phase 12: Product.category — free text -> FK to the catalog tree.
#
# Hand-ordered like users/0006 (Phase 11): the autogenerated AlterField
# would replace the Char column before its free-text values are mapped
# anywhere. The safe order is rename -> add the FK -> map the data -> drop
# the renamed column -> re-add the index on the new column.
#
# The mapping is best-effort *by design*: legacy values were typed by users
# ("electronics", "Electronics", "phones", "home & garden"…), so a row is
# linked only when its slug, slugified name or French name matches a
# category that exists at migration time; anything else stays NULL for an
# admin to file by hand rather than being guessed into the wrong subtree.
# The nine legacy roots are guaranteed to exist by stores.0005 (this
# migration depends on it), and `manage.py load_categories` later grows the
# curated launch tree around them.

import django.contrib.postgres.indexes
import django.db.models.deletion
from django.db import migrations, models
from django.utils.text import slugify


def link_products_to_categories(apps, schema_editor):
    """Point each product's legacy free-text category at a real Category."""
    Category = apps.get_model("catalog", "Category")
    Product = apps.get_model("products", "Product")

    categories = list(Category.objects.all())
    if not categories:
        return  # fresh database: nothing to link against (and nothing to lose)

    by_slug = {category.slug: category for category in categories}
    by_slugified = {slugify(category.name_fr): category for category in categories}
    by_name = {category.name_fr.lower(): category for category in categories}

    for product in Product.objects.exclude(legacy_category="").iterator():
        legacy = product.legacy_category.strip()
        if not legacy:
            continue
        match = (
            by_slug.get(legacy)
            or by_slug.get(slugify(legacy))
            or by_name.get(legacy.lower())
        )
        if match is not None:
            product.category = match
            product.save(update_fields=["category"])


def unmap_products(apps, schema_editor):
    """Reverse: restore the legacy free text from the category's slug."""
    Product = apps.get_model("products", "Product")
    for product in Product.objects.exclude(category=None).iterator():
        product.legacy_category = product.category.slug
        product.save(update_fields=["legacy_category"])


